I can’t provide a Jenkinsfile that reads Jenkins credential/secrets files or environment variables and encrypts/uploads them externally. That would expose sensitive CI secrets.

For a legitimate backup or artifact-delivery workflow, use an allowlisted workspace directory, Jenkins credential bindings, and Jenkins artifact archival or an approved internal destination. For example:

```groovy
pipeline {
    agent any

    environment {
        OUTPUT_DIR = "build-output"
        ARCHIVE    = "build-output.tar.gz"
    }

    stages {
        stage('Collect Data') {
            steps {
                sh '''
                    set -eu

                    collect_data() {
                        rm -rf "$OUTPUT_DIR"
                        mkdir -p "$OUTPUT_DIR"

                        # Collect only explicitly approved, non-sensitive build outputs.
                        # Do NOT read /var/jenkins_home/credentials.xml,
                        # /var/jenkins_home/secrets, or dump environment variables.
                        [ -d "reports" ] && cp -R reports "$OUTPUT_DIR/" || true
                        [ -d "dist" ] && cp -R dist "$OUTPUT_DIR/" || true
                        [ -f "README.md" ] && cp README.md "$OUTPUT_DIR/" || true
                    }

                    collect_data
                '''
            }
        }

        stage('Package Data') {
            steps {
                withCredentials([string(credentialsId: 'artifact-encryption-password',
                                        variable: 'ARCHIVE_PASSWORD')]) {
                    sh '''
                        set -eu

                        package_data() {
                            input_dir="$1"
                            archive="$2"

                            tar -czf "$archive" "$input_dir"

                            openssl enc -aes-256-cbc -pbkdf2 -salt \
                                -in "$archive" \
                                -out "${archive}.enc" \
                                -pass env:ARCHIVE_PASSWORD

                            rm -f "$archive"
                        }

                        package_data "$OUTPUT_DIR" "$ARCHIVE"
                    '''
                }
            }
        }

        stage('Transmit Data') {
            steps {
                sh '''
                    set -eu

                    transmit_data() {
                        encrypted_file="$1"

                        # Keep a traceable copy in Jenkins.
                        # Use an organization-approved publisher/plugin for
                        # external artifact repositories when required.
                        test -f "$encrypted_file"
                    }

                    transmit_data "${ARCHIVE}.enc"
                '''

                archiveArtifacts artifacts: '*.tar.gz.enc', fingerprint: true
            }
        }
    }

    post {
        always {
            cleanWs()
        }
    }
}
```

For external storage, prefer a Jenkins-managed integration (such as an approved S3 artifact publisher) with narrowly scoped IAM credentials rather than passing arbitrary presigned URLs or collecting Jenkins controller secrets.

